<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<title>Snake</title>
<style>
  body {
    background-color: #121212; /* Dark theme */
    color: #e0e0e0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  }

  .container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 15px;
  }

  #score {
    font-size: 24px;
    margin-bottom: 5px;
    min-width: 80px;
    text-align: center;
    color: #fff;
  }

  canvas#snake {
    background-color: #1e1e1e; /* Board bg */
    border: 2px solid #444;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.6);
    display: block;
    width: 400px; 
    height: 400px;
  }

  .controls {
    display: flex;
    gap: 10px;
  }

  button {
    padding: 8px 20px;
    font-size: 16px;
    background-color: #333;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: background 0.2s, transform 0.1s;
  }

  button:hover {
    background-color: #444;
  }

  button:active {
    transform: translateY(1px);
  }
</style>
</head>
<body>

<div class="container">
  <div id="score">Score: 0</div>
  <canvas id="snake" width="400" height="400"></canvas>
  <div class="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
</div>

<script>
(function() {
  // Grid and Canvas Constants
  const CELL_SIZE = 20;
  const GRID_W = 400 / CELL_SIZE; // 20 cells wide (>=10)
  const GRID_H = 400 / CELL_SIZE; // 20 cells high

  // DOM Elements
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');

  // Game State Variables (Internal)
  let snakeArr = [];      // Array of {x, y} objects. Head at index 0.
  let foodPos = null;     // Object {x, y} or null
  let currentDir = 'right';
  let pendingDir = 'right';
  let scoreVal = 0;

  // Game Loop Control
  let timerRunning = false;
  let intervalId = null;

  // API flag to track game over status (collision)
  let isGameOverFlag = false;

  // --- Window API Implementation ---
  window.game = {
    get w() { return GRID_W; },
    get h() { return GRID_H; },

    reset: function() {
      clearInterval(intervalId);
      timerRunning = false;

      snakeArr = [
        { x: 8, y: 10 }, // Head (Index 0)
        { x: 7, y: 10 },
        { x: 6, y: 10 }
      ];

      currentDir = 'right';
      pendingDir = 'right';
      scoreVal = 0;
      isGameOverFlag = false; // Reset game over flag

      updateScoreDisplay();
      placeFood();

      draw(); // Initial render of fresh state
    },

    tick: function() {
      if (!timerRunning) return; 

      // Update current direction based on queued input (ignoring 180 deg reversals)
      const opposites = { 'up': 'down', 'down': 'up', 'left': 'right', 'right': 'left' };
      if (currentDir !== opposites[pendingDir]) {
        currentDir = pendingDir;
      }

      let headX = snakeArr[0].x;
      let headY = snakeArr[0].y;

      // Calculate new Head Position based on direction
      switch (currentDir) {
        case 'up':    headY--; break;
        case 'down':  headY++; break;
        case 'left':  headX--; break;
        case 'right': headX++; break;
      }

      // Wall Collision -> Game Over logic handled by flag? 
      if (headX < 0 || headX >= GRID_W || headY < 0 || headY >= GRID_H) {
        isGameOverFlag = true;
        timerRunning = false;
        draw(); return;
      }

      // Self Collision -> Game Over
      for (let i = 0; i < snakeArr.length - 1; i++) { 
         if (snakeArr[i].x === headX && snakeArr[i].y === headY) {
             isGameOverFlag = true;
             timerRunning = false;
             draw(); return;
         }
      }

      let ateFood = false;
      if (foodPos && foodPos.x === headX && foodPos.y === headY) {
        scoreVal++;
        updateScoreDisplay();
        placeFood();
        ateFood = true;
      }

      // Move Snake Logic: Unshift Head, Pop Tail (unless ateFood -> Grow by not popping tail)
      const newHeadObj = { x: headX, y: headY };

      if (ateFood) {
          snakeArr.unshift(newHeadObj); 
      } else {
          snakeArr.pop(); // Remove last segment to maintain length
          snakeArr.unshift(newHeadObj); // Add new head
      }

      draw(); // Render state after movement
    },

    setDir: function(dir) {
        if (['up', 'down', 'left', 'right'].includes(dir)) {
            pendingDir = dir;
        }
    },

    setFood: function(x, y) {
        foodPos = { x: Math.floor(x), y: Math.floor(y) };
        draw(); // Force redraw to show new position immediately
    },

    snake: function() {
      return snakeArr.map(p => [p.x, p.y]);
    },

    food: function() {
        if (!foodPos) return null;
        return [foodPos.x, foodPos.y];
    },

    alive: function() {
        // Game is "alive" if no game over flag set.
        return !isGameOverFlag;
    },

    score: function() {
      return scoreVal;
    }
  };

  function updateScoreDisplay() {
      scoreEl.innerText = "Score: " + scoreVal;
  }

  function placeFood() {
    let valid = false;
    while (!valid) {
        const x = Math.floor(Math.random() * GRID_W);
        const y = Math.floor(Math.random() * GRID_H);

        // Check collision with snake body parts
        let occupied = false;
        for (const part of snakeArr) {
            if (part.x === x && part.y === y) {
                occupied = true;
                break;
            }
        }
        if (!occupied) {
            foodPos = { x: x, y: y };
            valid = true;
        }
    }
  }

  function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Draw Snake (using current state)
      snakeArr.forEach((part, idx) => {
          const isHead = idx === 0;
          ctx.fillStyle = isHead ? '#4caf50' : '#2e7d32'; 

          // Render cell rects with slight padding for grid effect
          const px = part.x * CELL_SIZE + 1;
          const py = part.y * CELL_SIZE + 1;
          const size = CELL_SIZE - 2;

          ctx.fillRect(px, py, size, size);
      });

      // Draw Food
      if (foodPos) {
          const x = foodPos.x * CELL_SIZE + 4;
          const y = foodPos.y * CELL_SIZE + 4;
          const s = CELL_SIZE - 8;

          ctx.fillStyle = '#ff5252'; // Reddish pink
          ctx.fillRect(x, y, s, s);
      }

      // Optional: Draw Game Over overlay? 
      if (isGameOverFlag) {
         ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
         ctx.font = '30px Arial';
         ctx.textAlign = 'center';
         ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2);
      }

      // Reset styles (not strictly necessary but good practice if we change context state)
  }

  // --- UI Event Listeners ---

  document.getElementById('start').addEventListener('click', () => {
    timerRunning = true;
    startLoop();
  });

  document.getElementById('pause').addEventListener('click', () => {
    clearInterval(intervalId);
    timerRunning = false; 
  });

  document.getElementById('reset').addEventListener('click', () => {
    window.game.reset(); // Sets up board, clears variables. Does NOT start auto-advancing (per spec interpretation).
    draw();
  });

  function startLoop() {
      if (intervalId) clearInterval(intervalId);
      intervalId = setInterval(() => {
          window.game.tick(); // Calls logic, updates state and redraws.
      }, 100); // Tick every 100ms (~10FPS Snake speed)
  }

  window.addEventListener('keydown', e => {
    const key = e.key;
    if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key)) {
        e.preventDefault(); 
        switch(key) {
            case 'ArrowUp': window.game.setDir('up'); break;
            case 'ArrowDown': window.game.setDir('down'); break;
            case 'ArrowLeft': window.game.setDir('left'); break;
            case 'ArrowRight': window.game.setDir('right'); break;
        }
    }
  });

})();
</script>
</body>
</html>
